mapper.select:
select r.id, r.customer_id, r.customer_name, r.reminder_time, r.content, r.status, r.receiver, r.create_user, r.create_time
from cus_reminder r
where r.organization_id = #{orgId}
and r.receiver = #{userId}

    and r.customer_id = #{request.customerId}


    and r.status = #{request.status}


    and r.content like concat('%', #{request.content}, '%')

order by r.reminder_time desc

select r.id, r.customer_id, r.customer_name, r.reminder_time, r.content, r.status, r.receiver, r.organization_id
from cus_reminder r
where r.organization_id = #{orgId}
and r.status = 'PENDING'
and r.reminder_time <= #{currentTime}

select count(1) from cus_reminder
where organization_id = #{orgId}
and receiver = #{userId}
and status = 'PENDING'
